'use strict'

const unpipe = require('unpipe')

class StreamHub {
  constructor(source) {
    if (!source || typeof source.pipe !== 'function') {
      throw new TypeError('StreamHub requires a readable source stream')
    }

    this.source = source
    this.destinations = new Set()
  }

  add(destination) {
    if (!destination || typeof destination.write !== 'function') {
      throw new TypeError('destination must be a writable stream')
    }

    this.destinations.add(destination)
    this.source.pipe(destination)
    return destination
  }

  remove(destination) {
    this.destinations.delete(destination)
    this.source.unpipe(destination)
    return destination
  }

  removeAll() {
    // `unpipe(source)` detaches the source from *every* destination Node knows
    // about, including pipes that were not registered through this hub.
    unpipe(this.source)
    this.destinations.clear()
  }
}

module.exports = StreamHub

'use strict'

const http = require('http')
const { Readable } = require('stream')
const StreamHub = require('./src/stream-hub')

const PORT = process.env.PORT || 3000

function createTicker() {
  let timer
  return new Readable({
    read() {
      this.push(`tick ${Date.now()}\n`)
      timer = setTimeout(() => this.read(0), 1000)
    },
    destroy(err, callback) {
      clearTimeout(timer)
      callback(err)
    },
  })
}

const server = http.createServer((req, res) => {
  if (req.url !== '/stream') {
    res.writeHead(404, { 'content-type': 'text/plain' })
    res.end('Not Found')
    return
  }

  res.writeHead(200, {
    'content-type': 'text/plain; charset=utf-8',
    'cache-control': 'no-cache',
  })

  const source = createTicker()
  const hub = new StreamHub(source)
  hub.add(res)

  let closed = false
  const cleanup = () => {
    if (closed) return
    closed = true
    hub.removeAll()
    source.destroy()
  }

  req.on('close', cleanup)
  res.on('close', cleanup)
})

if (require.main === module) {
  server.listen(PORT, () => {
    console.log(`listening on http://localhost:${PORT}`)
  })
}

module.exports = server

