Now the test. Use node:test and assert. Test the StreamHub.removeAll reliably unpipes from all destinations including untracked ones.

Test:
```js
'use strict'

const test = require('node:test')
const assert = require('node:assert')
const { PassThrough, Writable } = require('stream')
const unpipe = require('unpipe')
const StreamHub = require('../src/stream-hub')

function collector() {
  const chunks = []
  const w = new Writable({
    write(chunk, enc, cb) { chunks.push(chunk.toString()); cb() }
  })
  w.chunks = chunks
  return w
}

test('removeAll unpipes every tracked destination', () => {
  const source = new PassThrough()
  const hub = new StreamHub(source)
  const a = collector()
  const b = collector()
  hub.add(a)
  hub.add(b)

  hub.removeAll()

  source.write('after')
  assert.deepStrictEqual(a.chunks, [])
  assert.deepStrictEqual(b.chunks, [])
  assert.strictEqual(hub.destinations.size, 0)
})

test('removeAll unpipes destinations that were not tracked by the hub', () => {
  const source = new PassThrough()
  const hub = new StreamHub(source)
  const tracked = collector()
  const rogue = collector()
  hub.add(tracked)
  source.pipe(rogue) // piped directly, hub never saw it

  hub.removeAll()

  source.write('after')
  assert.deepStrictEqual(tracked.chunks, [])
  assert.deepStrictEqual(rogue.chunks, [])
})

test('remove drops a single destination and keeps the rest', () => {
  const source = new PassThrough()
  const hub = new StreamHub(source)
  const a = collector()
  const b = collector()
  hub.add(a)
  hub.add(b)

  hub.remove(a)
  source.write('after')

  assert.deepStrictEqual(a.chunks, [])
  assert.deepStrictEqual(b.chunks, ['after'])
})
```

Wait, there's a subtlety: streams pipe asynchronously? PassThrough pipe write is synchronous-ish; data written after pipe setup is delivered on next tick? Actually `source.write('after')` triggers 'data' event synchronously? Readable in flowing mode emits data. When you call `.pipe()`, it resumes the stream; `write` on a PassThrough triggers read and pushes data, which emits synchronously in the same tick typically. But to be safe, I should wait a tick before asserting. Let me add a small delay using `await setTimeout(10)` from timers/promises.

Let me restructure tests as async.

For the third test, after `source.write('after')`, b receives it. Good.

Let me write with `await new Promise(r => setImmediate(r))`.

Also, node --test discovers files under test/ or *.test.js. Let me name it `test/stream-hub.test.js`. `node --test` by default runs files matching test patterns. In Node 22, `node --test` without args runs test files in the current dir matching patterns like `**/*.test.js`. Good.

